					if child:IsA("TextLabel") and child.Name == "__IconFont" then
						applyKeyGrad(child)
					end
				end)
			end

			for _, child in ipairs(elem:GetChildren()) do
				if child:IsA("TextLabel") and child.Name == "__IconFont" then
					applyKeyGrad(child)
				end
			end
		end)
