	local origGetIcon = KeyLibrary.GetIcon
	KeyLibrary.GetIcon = function(self, IconName)
		if typeof(IconName) == "string" then
			local norm = string.lower(string.match(IconName, "^%s*(.-)%s*$") or IconName)
			if StandaloneIcons[norm] then
				return {
					Url = StandaloneIcons[norm],
					ImageRectOffset = Vector2.zero,
					ImageRectSize = Vector2.zero,
					Custom = true,
				}
			end
		end
		if origGetIcon then
			return origGetIcon(self, IconName)
		end
		return nil
	end

	local origApplyLucideIcon = KeyLibrary.ApplyLucideIcon
	KeyLibrary.ApplyLucideIcon = function(self, ImageGui, Icon, Rotation)
		if ImageGui and ImageGui:IsA("GuiObject") then
			local p = ImageGui.Parent
			local isMove = ImageGui.Name == "MoveIconImage"
				or (
					ImageGui.AnchorPoint.X == 1
					and ImageGui.SizeConstraint == Enum.SizeConstraint.RelativeYY
					and p
					and p:IsA("Frame")
				)
			local isResize = ImageGui.Name == "WindowResizeIcon"
				or ImageGui.Name == "ResizeGrabberIcon"
				or (p and p:IsA("TextButton") and p.SizeConstraint == Enum.SizeConstraint.RelativeYY)
				or (p and p.Name == "ResizeButton")

			if isMove then
				Icon = {
					Url = "rbxassetid://10734900011",
					ImageRectOffset = Vector2.zero,
					ImageRectSize = Vector2.zero,
					Custom = true,
				}
			elseif isResize then
				Icon = {
					Url = "rbxassetid://10734898934",
					ImageRectOffset = Vector2.zero,
					ImageRectSize = Vector2.zero,
					Custom = true,
				}
			end
		end
		if origApplyLucideIcon then
			local res = origApplyLucideIcon(self, ImageGui, Icon, Rotation)
			task.defer(function()
				if ImageGui and ImageGui.Parent then
					RegisterIfKeyLogo(ImageGui)
				end
			end)
			return res
		end
	end

