	local keyRotCounter = 0
	keyRenderConn = RunService.RenderStepped:Connect(function(dt)
		if not (KeyWindow and KeyWindow.MainFrame and KeyWindow.MainFrame.Parent) then
			if keyRenderConn then
				keyRenderConn:Disconnect()
			end
			return
		end
		keyRotCounter = (keyRotCounter + dt * 160) % 360
		if keyWindowStroke and keyWindowStroke.Parent then
			keyWindowStroke.Enabled = true
			keyWindowStroke.Thickness = 1.2
			keyWindowStroke.Transparency = 0.2
			keyWindowStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			keyWindowStroke.Color = Color3.fromRGB(255, 255, 255)
		end
		if keySidebarBeamHead and keySidebarDivider and keySidebarDivider.Parent then
			local totalH = keySidebarDivider.AbsoluteSize.Y
			if totalH > 20 then
				local flow = (os.clock() * 0.42) % 1
				local beamY = -85 + flow * (totalH + 170)
				keySidebarBeamHead.Position = UDim2.new(0, 0, 0, beamY)
			end
		end
		for _, g in ipairs(keyGradients) do
			if g and g.Parent and g.Name ~= "LaserGradient" then
				g.Rotation = keyRotCounter
			end
		end
		local sweepX = math.sin(os.clock() * 1.1) * 0.55
		for i = #keyNeonFlows, 1, -1 do
			local g = keyNeonFlows[i]
			if g and g.Parent then
				g.Offset = Vector2.new(sweepX, 0)
				if g.Parent:IsA("GuiObject") then
					g.Parent.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
					g.Parent.BackgroundTransparency = 0.2
				end
			else
				table.remove(keyNeonFlows, i)
			end
		end
	end)
