	local isVerifying = false
	local lastVerifyAttempt = 0
	local failedAttempts = 0
	local lastFailedPenalty = 0
	local function TriggerKeyVerification()
		if isVerifying then
			return
		end
		local now = os.clock()
		if now - lastVerifyAttempt < 1.0 then
			KeyLibrary:Notify({
				Title = "Cooldown",
				Description = "Please wait a moment before trying again.",
				Time = 2,
			})
			return
		end
		if failedAttempts >= 5 and now - lastFailedPenalty < 5.0 then
			local waitLeft = math.ceil(5.0 - (now - lastFailedPenalty))
			KeyLibrary:Notify({
				Title = "Rate Limited",
				Description = string.format("Too many failed attempts. Please wait %ds.", waitLeft),
				Time = 3,
			})
			KeyStatusLabel:SetText(string.format("Status: Rate limited (%ds remaining)", waitLeft))
			return
		end
		local inputKey = KeyOptions.InputKeyField and KeyOptions.InputKeyField.Value
		if not inputKey or #inputKey:gsub("%s+", "") == 0 then
			KeyLibrary:Notify({
				Title = "Key Required",
				Description = "Please paste your key into the text field.",
				Time = 3,
			})
			KeyStatusLabel:SetText("Status: Key field is empty")
			return
		end
		inputKey = inputKey:gsub("%s+", "")
		isVerifying = true
		lastVerifyAttempt = os.clock()
		KeyStatusLabel:SetText("Status: Verifying key with Junkie...")
		task.spawn(function()
			local valid, msg = VerifyKey(inputKey)
			isVerifying = false
			if valid then
				failedAttempts = 0
				SaveVerifiedKey(inputKey)
				keyAccepted = true
				getgenv().__VYNX_KeyWindowOpen = nil
				KeyStatusLabel:SetText("Status: Key Verified. Launching VYNX...")
				KeyLibrary:Notify({
					Title = "Access Granted",
					Description = "License verified! Initializing VYNX Hub...",
					Time = 3,
				})
				task.wait(0.6)
				if keyRenderConn then
					pcall(function()
						keyRenderConn:Disconnect()
					end)
				end
				pcall(function()
					KeyLibrary:Unload()
				end)
				task.wait(0.15)
				getgenv().SCRIPT_KEY = inputKey
			else
				failedAttempts = failedAttempts + 1
				if failedAttempts >= 5 then
					lastFailedPenalty = os.clock()
				end
				KeyStatusLabel:SetText("Status: " .. tostring(msg))
				KeyLibrary:Notify({
					Title = "Verification Failed",
					Description = tostring(msg),
					Time = 4,
				})
			end
		end)
	end
	KeyGroup:AddButton({
		Text = "Verify Key",
		Func = TriggerKeyVerification,
	})
	pcall(function()
		if keyBoxDefault and #keyBoxDefault:gsub("%s+", "") > 0 then
