	local function syncDiscord()
		pcall(function()
			local req = httpReq({
				Url = "https://discord.com/api/v10/invites/f7ZJXEXFKP?with_counts=true",
				Method = "GET",
			})
			if req and (req.StatusCode == 200 or req.Status == 200) and req.Body then
				local data = HttpService:JSONDecode(req.Body)
				if data and data.guild then
					local totalCount = data.approximate_member_count or 42
					local onlineCount = data.approximate_presence_count or 5
					local gName = data.guild.name or "VYNX"
					if gTitle then
						gTitle.Text = gName .. " Community"
					end
					if commMembersLabel then
						commMembersLabel:SetText(
							string.format('Members: <font color="#9A4BFF"><b>%d</b></font>', totalCount)
						)
					end
					if commOnlineLabel then
						commOnlineLabel:SetText(
							string.format('Online: <font color="#73f5af"><b>%d</b></font>', onlineCount)
						)
					end
					if data.guild.id and data.guild.icon and iconImg and iconImg.Parent then
						local iconUrl = string.format(
							"https://cdn.discordapp.com/icons/%s/%s.png?size=256",
							tostring(data.guild.id),
							tostring(data.guild.icon)
						)
						local assetPath = "VYNX/discord_server_icon.png"
						pcall(function()
							local imgReq = httpReq({ Url = iconUrl, Method = "GET" })
							local imgData = (imgReq and imgReq.Body)
								or (game and game.HttpGet and game:HttpGet(iconUrl))
							if imgData and #imgData > 100 and writefile then
								writefile(assetPath, imgData)
							end
							if isfile and isfile(assetPath) then
								local getAsset = getcustomasset or getsynasset
								if getAsset then
									iconImg.Image = getAsset(assetPath)
									iconImg.ImageColor3 = Color3.fromRGB(255, 255, 255)
								end
							end
						end)
					end
				end
			end
		end)
	end
	task.spawn(syncDiscord)
	_G.__VYNX_KeyCleanup = function()
		getgenv().__VYNX_KeyWindowOpen = nil
		if keyRenderConn then
			pcall(function()
				keyRenderConn:Disconnect()
			end)
			keyRenderConn = nil
		end
		pcall(function()
			if KeyLibrary and KeyLibrary.Unload then
				KeyLibrary:Unload()
			end
		end)
		pcall(function()
			local parent = SafeGetHui()
			for _, c in ipairs(parent:GetChildren()) do
				if c.Name == "Obsidian" then
					c:Destroy()
				end
			end
		end)
	end
end
if _G.__VYNX_KeyCleanup then
	pcall(_G.__VYNX_KeyCleanup)
	_G.__VYNX_KeyCleanup = nil
end
getgenv().__VYNX_KeyWindowOpen = nil
getgenv().__VYNX_UI_RUN = UI_RUN
getgenv().UI_CLOSED = false

local candidateKey = nil
if PRESET_KEY and type(PRESET_KEY) == "string" and #PRESET_KEY:gsub("%s+", "") > 0 then
	candidateKey = PRESET_KEY:gsub("%s+", "")
else
	local saved = LoadVerifiedKey()
	if saved and type(saved) == "string" and #saved:gsub("%s+", "") > 0 then
		candidateKey = saved:gsub("%s+", "")
	end
end

if candidateKey then
	EnsureJunkie()
	local autoValid = VerifyKey(candidateKey)
	if autoValid then
		SaveVerifiedKey(candidateKey)
		getgenv().SCRIPT_KEY = candidateKey
	else
		ClearSavedKey()
		LaunchKeySystem()
	end
else
	LaunchKeySystem()
end
while not getgenv().SCRIPT_KEY do
	if getgenv().UI_CLOSED or getgenv().__VYNX_UI_RUN ~= UI_RUN then
		return
	end
	task.wait(0.1)
end
